package cl.nexbyte.siger.institucional.nucleo;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import static cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
import static cl.nexbyte.siger.institucional.nucleo.NucleoU2.*;
import cl.nexbyte.siger.institucional.robustez.FalloTecnico;
import java.nio.file.Path;import java.util.*;

class NucleoU2Test {
 @TempDir Path temp;DatosAvisosTest f;NucleoU2 flow;
 @BeforeEach void setup()throws Exception{String mysql=System.getProperty("siger.test.autoridad.mysql");f=new DatosAvisosTest(temp,mysql==null?null:mysql+"_u2?sslMode=DISABLED&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000");flow=f.core.u2();}
 @AfterEach void close(){if(f!=null){f.close();}}
 NuevoDestino principal(){return new NuevoDestino("UPR","DEMO_SEDE_A",f.head);}
 UUID sol(UUID com){return flow.distribuir(f.a(f.dist),UUID.randomUUID(),com,new Encaminar(0,principal(),"Clasificación profesional sintética",null)).id();}
 UUID req(){return flow.asumir(f.a(f.head),UUID.randomUUID(),sol(f.manual()),new Asumir(0,f.prof,"Asunción de atención institucional",null)).id();}
 long count(String table){return f.d.db.sql.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 @Test void jefaturaAsumeSuPropioIngresoSinDistribuidor(){var com=f.core.registrarManual(f.a(f.head),UUID.randomUUID(),new Manual("Ingreso directo a jefatura","PRESENCIAL",f.tiempo.instant(),"DEMO_SEDE_A",null)).id();var r=new AsumirPropia(0,principal(),f.prof,"Asume su propio ingreso competente",null);denied(404,()->flow.asumirPropia(f.a(f.headOtra),UUID.randomUUID(),com,r));var q=flow.asumirPropia(f.a(f.head),UUID.randomUUID(),com,r);assertEquals("ACTIVO",flow.requerimiento(f.a(f.prof),q.id()).get("state"));assertEquals(0,count("core_case"));assertEquals(1,count("institution_sol"));}
 long rev(UUID req){return f.d.db.sql.queryForObject("SELECT revision FROM core_requirement WHERE id=?",Long.class,req.toString());}
 @Test void reintentoConfirmadoNoReejecutaTrabajoHistoricoNiAdmiteClaveNueva(){var com=f.d.nuevaWeb();var key=UUID.randomUUID();var r=new Distribucion(0,List.of(principal()));var result=f.core.distribuir(f.a(f.dist),key,com,r);assertEquals(result,f.core.soloReintento(f.a(f.dist),key,()->f.core.distribuir(f.a(f.dist),key,com,r)));denied(409,()->f.core.soloReintento(f.a(f.dist),UUID.randomUUID(),()->f.core.distribuir(f.a(f.dist),UUID.randomUUID(),com,r)));denied(409,()->f.core.soloReintento(f.a(f.dist),key,()->f.core.distribuir(f.a(f.dist),key,com,new Distribucion(1,r.destinos()))));assertEquals(1,count("core_destination"));assertEquals(0,count("core_requirement"));}
 @Test void administrativoResuelveAtencionPropiaSinAdquirirResponsabilidadProfesional(){String admin=f.cuenta("primera.admin","UPR","DEMO_SEDE_A","ADMINISTRATIVO","UNIDAD_SEDE");var q=flow.primeraAtencion(f.a(admin),UUID.randomUUID(),new PrimeraAtencion(new Manual("Atención simple propia","PRESENCIAL",f.tiempo.instant(),"DEMO_SEDE_A",null),principal(),"Orientación efectivamente entregada")).id();assertEquals("TERMINADO",flow.requerimiento(f.a(admin),q).get("state"));var sol=sol(f.d.nuevaWeb());denied(400,()->flow.asumir(f.a(f.head),UUID.randomUUID(),sol,new Asumir(0,admin,"Asignación profesional sin facultad",null)));assertEquals("PENDIENTE",flow.solicitud(f.a(f.head),sol).get("state"));assertEquals(1,count("core_requirement"));assertEquals(0,count("core_case"));}
 @Test void capturaYPrincipalSonDistintosCuandoExisteFacultadExplicita(){String jefe=f.cuenta("jefe.sede.b","UEP","DEMO_SEDE_B","COORDINADOR","UNIDAD_SEDE");ConcesionFixture.otorgar(f.d.db,f.ids,f.ti,f.prof,new cl.nexbyte.siger.institucional.identidad.IdentidadInstitucional.Otorgar("PROFESIONAL","UNIDAD_SEDE","UEP","DEMO_SEDE_B",f.tiempo.instant().minusSeconds(1),null),f.tiempo);var body=new PrimeraAtencion(new Manual("Captura propia en sede A","TELÉFONO",f.tiempo.instant(),"DEMO_SEDE_A",null),new NuevoDestino("UEP","DEMO_SEDE_B",jefe),"Atención bajo facultad explícita de sede B");var q=flow.primeraAtencion(f.a(f.prof),UUID.randomUUID(),body).id();var row=flow.requerimiento(f.a(jefe),q);assertEquals("DEMO_SEDE_B",row.get("site_id"));var com=UUID.fromString(row.get("communication_id").toString());assertEquals("DEMO_SEDE_A",f.core.detalle(f.a(f.prof),com).comunicacion().sedeOrigen());assertEquals(0,count("core_case"));}
 @Test void destinoTecnicoAsumidoNoApareceComoEvaluacionPendiente(){var q=req();var com=UUID.fromString(flow.requerimiento(f.a(f.head),q).get("communication_id").toString());var d=f.core.detalle(f.a(f.head),com);assertTrue(d.comunicacion().requerimientoInstitucional());assertNotNull(d.comunicacion().solicitudInstitucionalId());assertEquals(0,d.comunicacion().destinosPendientes());assertTrue(d.destinos().isEmpty());assertEquals("ACTIVO",d.comunicacion().estadoRequerimiento());}
 @Test void registradorConservaSuOriginalSinObtenerGestionDeReqAjeno(){var com=f.manual();var sol=sol(com);assertNotNull(f.core.detalle(f.a(f.prof),com));var q=flow.asumir(f.a(f.head),UUID.randomUUID(),sol,new Asumir(0,f.head,"La jefatura asume personalmente",null)).id();denied(404,()->flow.requerimiento(f.a(f.prof),q));assertNotNull(f.core.detalle(f.a(f.prof),com));assertEquals(1,f.core.buscar(f.a(f.prof),"",false,0,20).total());assertEquals("ACTIVO",flow.requerimiento(f.a(f.head),q).get("state"));}
 @Test void distribuidorEncuentraReferenciaMinimaSinContenidoNiEleccionDeCaso(){var q=req();var row=flow.requerimiento(f.a(f.head),q);var com=UUID.fromString(row.get("communication_id").toString());var folio=f.core.detalle(f.a(f.prof),com).comunicacion().folio();var references=flow.referencias(f.a(f.dist),folio);assertEquals(1,references.size());assertEquals(q.toString(),references.getFirst().get("requirement_id"));assertEquals(Set.of("requirement_id","communication_id","state","unit_code","site_id"),references.getFirst().keySet());denied(404,()->f.core.detalle(f.a(f.dist),com));denied(403,()->flow.referencias(f.a(f.ti),folio));var c=flow.abrirCaso(f.a(f.head),UUID.randomUUID(),q,new Apertura(0,f.prof,"Objetivo propio")).id();var child=f.d.nuevaWeb();denied(409,()->f.core.vincular(f.a(f.dist),UUID.randomUUID(),child,new Vinculacion(com,c,"El distribuidor no determina el Caso")));f.core.vincular(f.a(f.dist),UUID.randomUUID(),child,new Vinculacion(com,null,"Propuesta únicamente al REQ"));assertEquals(q.toString(),f.d.db.sql.queryForObject("SELECT requirement_reference FROM core_link WHERE child_id=?",String.class,child.toString()));}
 @Test void fallaDeAuditoriaRevierteNacimientoYPermiteReintentoMismaClave(){var sol=sol(f.d.nuevaWeb());var key=UUID.randomUUID();var body=new Asumir(0,f.prof,"Asunción a probar atómicamente",null);f.d.ddl(sql->sql.execute("ALTER TABLE institution_flow_history ADD CONSTRAINT test_u2_history CHECK(action_code <> 'REQ_NACIDO_POR_ASUNCION')"));try{assertThrows(org.springframework.dao.DataAccessException.class,()->flow.asumir(f.a(f.head),key,sol,body));}finally{f.d.ddl(sql->sql.execute("ALTER TABLE institution_flow_history DROP "+(System.getProperty("siger.test.autoridad.mysql")==null?"CONSTRAINT":"CHECK")+" test_u2_history"));}assertEquals(0,count("core_requirement"));assertEquals("PENDIENTE",flow.solicitud(f.a(f.head),sol).get("state"));assertEquals(0,f.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_command WHERE id=?",Long.class,key.toString()));flow.asumir(f.a(f.head),key,sol,body);assertEquals(1,count("core_requirement"));}
 @Test void carreraCerrarReqContraAbrirCasoConservaEstadoCoherente()throws Exception{var q=req();try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var close=pool.submit(()->{start.await();try{flow.actuar(f.a(f.head),UUID.randomUUID(),q,new Decision(0,"Cierre global concurrente"),true);return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}});var open=pool.submit(()->{start.await();try{flow.abrirCaso(f.a(f.head),UUID.randomUUID(),q,new Apertura(0,f.prof,"Objetivo concurrente"));return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}});start.countDown();assertNotEquals(close.get(),open.get());var r=flow.requerimiento(f.a(f.head),q);assertEquals("TERMINADO".equals(r.get("state"))?0:1,count("core_case"));}}
 void denied(int status,Runnable op){assertEquals(status,assertThrows(FalloTecnico.class,op::run).status);}
 @Test void primeraTelefonicaCreaComYReqCerradoSinCasoEsIdempotente(){var m=new Manual("Consulta telefónica sintética con respuesta","TELÉFONO",f.tiempo.instant().minusSeconds(1),"DEMO_SEDE_A",null);var r=new PrimeraAtencion(m,principal(),"Se explicó la orientación.\nSe resolvió la consulta concreta.");var key=UUID.randomUUID();var result=flow.primeraAtencion(f.a(f.prof),key,r);assertEquals(result,flow.primeraAtencion(f.a(f.prof),key,r));assertEquals(r.respuesta(),f.d.db.sql.queryForObject("SELECT reason_text FROM institution_flow_history WHERE resource_id=? AND action_code='PRIMERA_ATENCION_RESUELTA'",String.class,result.id().toString()));assertEquals(0,count("core_case"));assertEquals(0,count("institution_sol"));assertEquals(1,count("core_requirement"));var q=flow.requerimiento(f.a(f.prof),result.id());assertEquals("TERMINADO",q.get("state"));assertEquals("UPR",q.get("unit_code"));var com=UUID.fromString(q.get("communication_id").toString());assertEquals(m.texto(),f.core.detalle(f.a(f.prof),com).contenido().texto());denied(409,()->flow.abrirCaso(f.a(f.head),UUID.randomUUID(),result.id(),new Apertura(1,f.prof,"Objetivo posterior")));}
 @Test void webNoCreaAgregadosDistribucionSoloSolAsuncionCreaReqSinCaso(){var com=f.d.nuevaWeb();assertEquals(0,count("core_requirement"));assertEquals(0,count("institution_sol"));var sol=sol(com);assertEquals(0,count("core_requirement"));denied(404,()->flow.asumir(f.a(f.prof),UUID.randomUUID(),sol,new Asumir(0,f.prof,"No es jefatura",null)));var key=UUID.randomUUID();var r=new Asumir(0,f.prof,"Evaluación y asignación sintética",null);var req=flow.asumir(f.a(f.head),key,sol,r);assertEquals(req,flow.asumir(f.a(f.head),key,sol,r));assertEquals(1,count("core_requirement"));assertEquals(0,count("core_case"));flow.actuar(f.a(f.prof),UUID.randomUUID(),req.id(),new Decision(0,"Atención profesional y respuesta concreta"),true);assertEquals("TERMINADO",flow.requerimiento(f.a(f.head),req.id()).get("state"));}
 @Test void variosCasosUnReqConObjetivosYComplejidadSoloGlobalCierreExplicito(){var q=req();flow.clasificar(f.a(f.head),UUID.randomUUID(),q,new Clasificacion(0,"MEDIANA","Criterio profesional de jefatura"));var c1=flow.abrirCaso(f.a(f.head),UUID.randomUUID(),q,new Apertura(1,f.prof,"Objetivo independiente primero")).id();var c2=flow.abrirCaso(f.a(f.head),UUID.randomUUID(),q,new Apertura(2,f.prof,"Objetivo independiente segundo")).id();assertEquals(1,count("core_requirement"));assertEquals(q,f.core.caso(f.a(f.prof),c1).requerimientoId());assertEquals(q,f.core.caso(f.a(f.prof),c2).requerimientoId());assertNull(f.core.caso(f.a(f.prof),c1).clasificacion());denied(409,()->f.core.clasificar(f.a(f.head),UUID.randomUUID(),c1,new Clasificacion(0,"BAJA","No clasificar Caso")));denied(409,()->flow.actuar(f.a(f.head),UUID.randomUUID(),q,new Decision(3,"Cierre anticipado"),true));for(var c:List.of(c1,c2)){f.core.revisarCaso(f.a(f.prof),UUID.randomUUID(),c,new Decision(0,"Solicitud de cierre fundada"),"SOLICITUD_TERMINO");f.core.revisarCaso(f.a(f.head),UUID.randomUUID(),c,new Decision(1,"Revisión independiente y confirmación"),"CIERRE");}assertEquals("ACTIVO",flow.requerimiento(f.a(f.head),q).get("state"));flow.actuar(f.a(f.head),UUID.randomUUID(),q,new Decision(3,"Cierre global explícito"),true);assertEquals("TERMINADO",flow.requerimiento(f.a(f.head),q).get("state"));}
 @Test void redireccionConservaSolSinReqYRetiraAccesoDelDestinoAnterior(){var com=f.d.nuevaWeb();var sol=sol(com);var other=new NuevoDestino("UPD","DEMO_SEDE_A",f.headOtra);var r=new Encaminar(0,other,"Rectificación fundada de clasificación",null);var key=UUID.randomUUID();assertEquals(flow.redirigir(f.a(f.head),key,sol,r),flow.redirigir(f.a(f.head),key,sol,r));assertEquals(1,count("institution_sol"));assertEquals(2,count("core_destination"));assertEquals(0,count("core_requirement"));denied(404,()->f.core.detalle(f.a(f.head),com));assertEquals(0,f.core.buscar(f.a(f.head),"",false,0,20).total());assertEquals(0,f.core.bandeja(f.a(f.head)).comunicaciones());assertEquals(sol,UUID.fromString(flow.solicitud(f.a(f.headOtra),sol).get("id").toString()));flow.asumir(f.a(f.headOtra),UUID.randomUUID(),sol,new Asumir(1,f.otro,"Asunción por jefatura receptora",null));assertEquals(1,count("core_requirement"));}
 @Test void colaboracionAceptadaCreaCasoParaleloYNoDaAccesoAlOriginalNiGestionPrincipal(){var q=req();var r=new Colaborar(0,new NuevoDestino("UPD","DEMO_SEDE_A",f.headOtra),"Intervención propia de la otra unidad");var p=flow.colaborar(f.a(f.head),UUID.randomUUID(),q,r);denied(409,()->flow.actuar(f.a(f.head),UUID.randomUUID(),q,new Decision(1,"Aún pendiente"),true));assertEquals(0,count("core_case"));var key=UUID.randomUUID();var decision=new ResolverColaboracion(0,"ACEPTADA",f.otro,"Se acepta el objetivo limitado");assertEquals(flow.resolver(f.a(f.headOtra),key,p.id(),decision),flow.resolver(f.a(f.headOtra),key,p.id(),decision));var caso=UUID.fromString(f.d.db.sql.queryForObject("SELECT case_id FROM institution_collaboration WHERE id=?",String.class,p.id().toString()));assertEquals(q,f.core.caso(f.a(f.otro),caso).requerimientoId());denied(404,()->flow.requerimiento(f.a(f.headOtra),q));var com=UUID.fromString(flow.requerimiento(f.a(f.head),q).get("communication_id").toString());denied(404,()->f.core.detalle(f.a(f.otro),com));assertEquals(0,f.core.buscar(f.a(f.otro),"",false,0,20).total());assertEquals(1,count("core_requirement"));assertEquals("UPR",flow.requerimiento(f.a(f.head),q).get("unit_code"));denied(409,()->f.core.solicitarDerivacion(f.a(f.headOtra),UUID.randomUUID(),caso,new SolicitarDerivacion(0,"UPR","DEMO_SEDE_A","Motivo","Paquete")));}
 @Test void retiroYRechazoConservanHistoriaYNoFabricanCasos(){var q=req();var p=flow.colaborar(f.a(f.head),UUID.randomUUID(),q,new Colaborar(0,new NuevoDestino("UPD","DEMO_SEDE_A",f.headOtra),"Objetivo propuesto"));flow.resolver(f.a(f.headOtra),UUID.randomUUID(),p.id(),new ResolverColaboracion(0,"RECHAZADA",null,"No corresponde la intervención"));assertEquals(0,count("core_case"));flow.actuar(f.a(f.prof),UUID.randomUUID(),q,new Decision(2,"Respuesta final sin Caso"),true);assertEquals("TERMINADO",flow.requerimiento(f.a(f.head),q).get("state"));assertTrue(count("institution_flow_history")>=4);}
 @Test void falloPrimeraAtencionNoDejaComNiReqYTiNoObtieneFacultad(){var m=new Manual("Atención sintética sin respuesta","TELÉFONO",f.tiempo.instant(),"DEMO_SEDE_A",null);denied(400,()->flow.primeraAtencion(f.a(f.prof),UUID.randomUUID(),new PrimeraAtencion(m,principal(),"")));assertEquals(0,count("communication_registry"));denied(403,()->flow.primeraAtencion(f.a(f.ti),UUID.randomUUID(),new PrimeraAtencion(m,principal(),"Respuesta no habilitada")));assertEquals(0,count("core_requirement"));}
 @Test void versionYConcurrenciaNoCreanDosReq()throws Exception{var sol=sol(f.d.nuevaWeb());try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var jobs=new ArrayList<java.util.concurrent.Future<Boolean>>();for(int i=0;i<2;i++)jobs.add(pool.submit(()->{start.await();try{flow.asumir(f.a(f.head),UUID.randomUUID(),sol,new Asumir(0,f.prof,"Asunción concurrente",null));return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}}));start.countDown();int successes=0;for(var j:jobs)if(j.get())successes++;assertEquals(1,successes);}assertEquals(1,count("core_requirement"));}
}
